drawMap=function(c,n,cam,g){c.save();c.translate(-cam.x,-cam.y);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const q=MAP[y][x],X=x*T,Y=y*T;if(q==="W"){c.fillStyle="#287fa8";c.fillRect(X,Y,T,T);c.fillStyle="#66bfd3";const z=Math.floor(n/220+y*2+x)%17;c.fillRect(X+z,Y+8,11,2);c.fillRect(X+(z+9)%19,Y+23,8,2)}else if(q==="P"){c.fillStyle="#78552f";c.fillRect(X,Y,T,T);c.fillStyle="#bc8950";for(let i=2;i<32;i+=8)c.fillRect(X+i,Y+2,5,28)}else if(q==="T"){c.fillStyle="#4f873d";c.fillRect(X,Y,T,T);c.fillStyle="#214e35";c.fillRect(X+3,Y+3,26,23);c.fillStyle="#327249";c.fillRect(X+8,Y,16,8)}else{c.fillStyle=q==="H"?"#d9c38e":(x+y)%2?"#86b957":"#80b153";c.fillRect(X,Y,T,T)}}TREE_POSITIONS.forEach(([x,y,s])=>drawTree(c,x*T,y*T,s));drawSnag(c,n);drawSchool(c,g,n);if(!g.player.inBoat)boat(c,BOAT.x,BOAT.y,"right",false,n);c.restore()};
