function fightingFishImage(s){const src=s.image||SPRITE;fishArt.images||(fishArt.images={});if(!fishArt.images[src]){const img=fishArt.images[src]=new Image;img.src=src}return fishArt.images[src]}
function drawFightingFish(c,g,n,q){if(g.mode!=="battle"||!g.fish||g.fish.weight<=6)return;const phase=(n-(g.battle.startedAt||n))%2300;if(phase>820)return;const t=phase/820,jump=Math.sin(t*Math.PI),side=Math.cos(t*Math.PI)*18,s=BY[g.fish.speciesId],img=fightingFishImage(s);if(!img?.naturalWidth)return;c.save();c.translate(q.x+side,q.y-jump*48);c.rotate((t-.5)*.8);c.imageSmoothingEnabled=false;if(s.image)c.drawImage(img,-31,-16,62,32);else{const sw=img.naturalWidth/4,sh=img.naturalHeight/3;c.drawImage(img,(s.sprite%4)*sw,Math.floor(s.sprite/4)*sh,sw,sh,-31,-16,62,32)}c.strokeStyle="rgba(220,250,255,.85)";c.lineWidth=2;c.beginPath();c.arc(-8,jump*48,10+8*t,Math.PI,0);c.arc(9,jump*48,8+7*t,Math.PI,0);c.stroke();c.restore()}
drawRod=function(c,g,n,x,y){const d=DIR[g.cast?.dir||g.chargeContext?.dir||g.player.facing]||DIR.right,charge=g.mode==="charging"?clamp((n-g.chargeAt)/1600,0,1):0,castSwing=g.mode==="waiting"&&g.castAnimationAt?clamp(1-(n-g.castAnimationAt)/380,0,1):0,lift=charge*36+castSwing*28,pull=g.mode==="battle"?Math.sin(n/85)*(7+(g.battle?.tension||0)*.08):0,b={x:x+d[0]*7,y:y-7+d[1]*3},tip={x:b.x+d[0]*(31-Math.abs(pull)*.35)-d[0]*charge*12,y:b.y+d[1]*31+Math.abs(pull)-lift};c.strokeStyle="#4b2d18";c.lineWidth=4;c.beginPath();c.moveTo(b.x,b.y);c.quadraticCurveTo(b.x+d[0]*20-d[1]*pull,b.y+d[1]*20+d[0]*pull-lift*.55,tip.x,tip.y);c.stroke();if(!g.cast||!["waiting","hooked","battle"].includes(g.mode))return;const q=g.cast.target,elapsed=n-(g.bobberAnimationAt||0),fighting=["hooked","battle"].includes(g.mode),animating=fighting&&elapsed>=0&&elapsed<560,sink=animating?clamp((elapsed-80)/390,0,1):0,w=g.mode==="waiting"?Math.sin(n/170)*1.5:sink*17;c.strokeStyle="rgba(255,255,255,.9)";c.lineWidth=1;c.beginPath();c.moveTo(tip.x,tip.y);c.quadraticCurveTo((tip.x+q.x)/2,Math.min(tip.y,q.y)-8-pull,q.x,q.y+w);c.stroke();if(g.mode==="waiting"||animating){c.globalAlpha=1-sink*.72;c.strokeStyle="rgba(215,249,255,.8)";c.beginPath();c.ellipse(q.x,q.y+4,8+sink*10,3+sink*4,0,0,Math.PI*2);c.stroke();c.fillStyle="#fff";c.fillRect(q.x-3,q.y-4+w,6,5);c.fillStyle="#e94b35";c.fillRect(q.x-3,q.y-7+w,6,4);c.globalAlpha=1}drawFightingFish(c,g,n,q)};
cast=function(g,p,c){g.castAnimationAt=performance.now();return castV5(g,p,c)};
function dryCastTease(g){const d=DIR[g.player.facing]||DIR.right,q=tile(g.player.x+d[0]*T,g.player.y+d[1]*T),x=g.player.x/T,y=g.player.y/T;if(q==="T")return"Vai pescar passarinho agora? A árvore não morde a isca!";if(q==="H")return"Essa casa até tem telhado, mas peixe mesmo não tem!";if(x<11)return"Desse lado a boia vai cair no mato. O peixe agradece!";if(x>25)return"Na margem leste desse jeito você só fisga capim!";if(y<7)return"Mais para o norte só se o peixe aprender a andar em terra!";if(y>14)return"No sul da margem? A minhoca vai voltar mais limpa do que entrou!";return"No meio do nada? A boia pediu um mapa antes do arremesso!"}
startCharge=function(g){if(g.mode!=="explore")return action(g);if(nearBoat(g)){g.player.inBoat=true;g.player.x=BOAT.x;g.player.y=BOAT.y;g.player.facing="right";return message(g,"Você embarcou na lancha! Navegue pela represa.",1800)}if(nearDock(g)){g.player.inBoat=false;g.player.x=8.35*T;g.player.y=10.5*T;g.player.facing="left";return message(g,"Você desembarcou no píer.",1500)}const c=context(g);if(!c)return characterSpeech(g,dryCastTease(g));g.mode="charging";g.chargeAt=performance.now();g.chargeContext=c};
controls=function(g){controlsV5(g);window.addEventListener("keydown",e=>{if(game!==g||e.repeat||e.code!=="KeyA"||g.mode!=="explore"||context(g)||nearBoat(g)||nearDock(g))return;e.preventDefault();g.keys.left=false;startCharge(g)},{signal:g.abort.signal})};
function rankingPlayerKey(){return window.firebase?.auth?.().currentUser?.uid||playerId()}
function bestProgressFish(progress){const captures=Array.isArray(progress?.captures)?progress.captures:[],fromCapture=captures.reduce((best,c)=>!best||+c.weight>+best.weight||(+c.weight===+best.weight&&+c.length>+best.length)?c:best,null),fromRecords=Object.entries(progress?.records||{}).reduce((best,[speciesId,r])=>{const item={speciesId,speciesName:BY[speciesId]?.name||speciesId,bestWeight:+r?.weight||0,bestLength:+r?.length||0,bestAt:Date.parse(r?.recordDate)||0};return!best||item.bestWeight>best.bestWeight||(item.bestWeight===best.bestWeight&&item.bestLength>best.bestLength)?item:best},null);if(fromCapture&&(!fromRecords||+fromCapture.weight>=fromRecords.bestWeight))return{speciesId:fromCapture.speciesId,speciesName:fromCapture.speciesName,bestWeight:+fromCapture.weight||0,bestLength:+fromCapture.length||0,bestAt:Date.parse(fromCapture.capturedAt)||0};return fromRecords}
function mergeRankingEntries(rankingRows=[],progressRows=[]){const rows=rankingRows.map(x=>({...x,bestWeight:+x.bestWeight||0,bestLength:+x.bestLength||0,captures:+x.captures||0}));for(const p of progressRows){const best=bestProgressFish(p);if(!best?.bestWeight)continue;const uid=p.userId||p.id||"",exact=rows.find(x=>(uid&&x.ownerUid===uid)||(x.speciesId===best.speciesId&&+x.bestWeight===best.bestWeight&&+x.bestLength===best.bestLength));if(exact){if(uid&&!exact.ownerUid)exact.ownerUid=uid;if(!exact.name&&p.playerName)exact.name=p.playerName;exact.captures=Math.max(exact.captures,+p.stats?.totalFishCaught||0);continue}rows.push({...best,id:`cloud-${uid}`,ownerUid:uid,name:p.playerName||`Pescador ${String(uid).slice(-4).toUpperCase()}`,captures:+p.stats?.totalFishCaught||0,updatedAt:+p.updatedAt||0})}const grouped=new Map;for(const row of rows){const normalized=String(row.name||row.id||"pescador").trim().toLocaleLowerCase("pt-BR"),key=row.ownerUid?`uid:${row.ownerUid}`:`name:${normalized}`,current=grouped.get(key);if(!current||row.bestWeight>current.bestWeight||(row.bestWeight===current.bestWeight&&row.bestLength>current.bestLength))grouped.set(key,{...(current||{}),...row,captures:Math.max(+current?.captures||0,+row.captures||0)});else current.captures=Math.max(+current.captures||0,+row.captures||0)}return[...grouped.values()].sort((a,b)=>b.bestWeight-a.bestWeight||b.bestLength-a.bestLength)}
saveRanking=async function(c){try{if(!window.firebase?.database)return;const authUser=window.firebase?.auth?.().currentUser||null,uid=authUser?.uid||playerId(),fallback=authUser?.displayName||String(authUser?.email||"").split("@")[0]||`Pescador ${uid.slice(-4).toUpperCase()}`,name=playerName(true)||fallback,now=Date.now();if(!localStorage.getItem(PNAME))localStorage.setItem(PNAME,name);if(game?.progress){game.progress.playerName=name;save(game.progress)}await firebase.database().ref(`jogos/olaPesca/ranking/${uid}`).transaction(v=>{const better=!v||c.weight>+(v.bestWeight||0)||(c.weight===+(v.bestWeight||0)&&c.length>+(v.bestLength||0));return{...(v||{}),name,ownerUid:authUser?.uid||v?.ownerUid||"",captures:+(v?.captures||0)+1,bestWeight:better?c.weight:+(v?.bestWeight||0),bestLength:better?c.length:+(v?.bestLength||0),speciesName:better?c.speciesName:v?.speciesName||c.speciesName,speciesId:better?c.speciesId:v?.speciesId||c.speciesId,bestAt:better?now:+v?.bestAt||now,updatedAt:now}})}catch(e){console.warn("Ranking do Pesque e Solte indisponível",e)}};
loadRanking=async function(d){const box=d.querySelector("[data-ranking-list]");if(!window.firebase?.database){box.innerHTML=`<p class="pesca-empty">Ranking indisponível agora.</p>`;return}try{const db=firebase.database(),[rankingSnap,usersSnap]=await Promise.all([db.ref("jogos/olaPesca/ranking").once("value"),db.ref("jogos/olaPesca/users").once("value").catch(()=>null)]),rankingRows=[],progressRows=[];rankingSnap.forEach(x=>rankingRows.push({...x.val(),id:x.key}));usersSnap?.forEach(x=>progressRows.push({...x.val(),id:x.key,userId:x.val()?.userId||x.key}));const a=mergeRankingEntries(rankingRows,progressRows),viewer=rankingPlayerKey(),authUid=window.firebase?.auth?.().currentUser?.uid||"";box.innerHTML=a.length?a.map((x,i)=>{const f=BY[x.speciesId]||FISH.find(v=>v.name===x.speciesName)||FISH[0],me=x.id===viewer||!!authUid&&x.ownerUid===authUid;return`<article class="pesca-rank-item ${me?"me":""}"><b>${i+1}</b><button class="pesca-rank-fish" data-rank-preview="${i}" aria-label="Ampliar ${esc(x.speciesName||"peixe")}"><i class="fish-sprite" style="${sprite(f)}"></i></button><div><strong>${esc(x.name||"Pescador")}</strong><small>Maior: ${esc(x.speciesName||"Peixe")} • ${(+x.bestLength||0).toLocaleString("pt-BR")} cm</small></div><span>${fmt(+x.bestWeight||0)}</span></article>`}).join(""):`<p class="pesca-empty">Seja o primeiro pescador no ranking!</p>`;box.querySelectorAll("[data-rank-preview]").forEach(b=>b.onclick=()=>{const x=a[+b.dataset.rankPreview];openFishPreview(game,{speciesId:x.speciesId,weight:x.bestWeight,length:x.bestLength,owner:x.name||"Pescador"})})}catch(e){console.warn("Falha ao consolidar ranking",e);box.innerHTML=`<p class="pesca-empty">Não foi possível carregar o ranking.</p>`}};
